"""One-time Okna45 update bootstrap. Run only from the MicroPython REPL.
Close the running OS first. Copy update SIN files to flash after this script.
"""
import os
import binascii

def _write(path, payload):
    with open(path + '.new', 'wb') as file:
        file.write(binascii.a2b_base64(payload))
        file.flush()
    getattr(os, 'replace', os.rename)(path + '.new', path)
    if hasattr(os, 'sync'):
        os.sync()

_write('/boot.py', b'IiIiU3RhYmxlIHJlY292ZXJ5IGhvb2suIEtlZXAgdGhpcyBhbmQgb2s0NV9ib290LnB5IG91dHNpZGUgcmVndWxhciB1cGRhdGVzLiIiIgpmcm9tIG9rNDVfYm9vdCBpbXBvcnQgcmVjb3ZlciwgbWFya19ib290CnJlY292ZXIoKQpyZWNvdmVyKCcvc3lzdGVtL3BrZycsICcvc3lzdGVtL3BrZy9pbnN0YWxsZWQuanNvbicpCm1hcmtfYm9vdCgpCg==')
_write('/ok45_boot.py', b'')
_write('/ok45_fs.py', b'')
_write('/ok45_sin.py', b'')
_write('/ok45_tx.py', b'')
_write('/ok45_update.py', b'')
_write('/update.py', b'')
print('Bootstrap installed. Copy both SIN files, restart to PicoTerm, then run: update /okna45-system-0.2.0.sin; update /okna45-software-0.2.0.sin; reboot.')
